// Customer Service Costs Retrieval
// Fetches most recent service costs for a customer from Partner Center API

var customerId = input.get("customerId");
var accessToken = input.get("accessToken");

if (!customerId || customerId.trim() === "") {
    log.error("Customer ID is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Customer ID is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else if (!accessToken || accessToken.trim() === "") {
    log.error("Access Token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access Token is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else {
    try {
        var url = "https://api.partnercenter.microsoft.com/v1/customers/" + customerId.trim() + "/servicecosts/MostRecent/lineitems";

        log.info("Fetching service costs for customer: " + customerId);

        var response = http.get(url, {
            "Authorization": "Bearer " + accessToken.trim(),
            "Accept": "application/json"
        });

        output.set("StatusCode", response.statusCode);
        output.set("Body", response.body);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            var data = json.parse(response.body);

            output.set("TotalCount", data.totalCount || 0);

            var items = data.items || [];
            output.set("LineItems", json.stringify(items));
            output.set("LineItemCount", items.length);

            // Calculate totals
            var pretaxTotal = 0;
            var taxTotal = 0;
            var afterTaxTotal = 0;
            var totalQuantity = 0;

            // Track unique subscriptions and offers
            var subscriptions = {};
            var offers = {};
            var chargeTypes = {};
            var customerName = "";
            var currencyCode = "";
            var currencySymbol = "";

            for (var i = 0; i < items.length; i++) {
                var item = items[i];

                pretaxTotal += item.pretaxTotal || 0;
                taxTotal += item.tax || 0;
                afterTaxTotal += item.afterTaxTotal || 0;
                totalQuantity += item.quantity || 0;

                if (item.subscriptionId) {
                    subscriptions[item.subscriptionId] = item.subscriptionFriendlyName || item.subscriptionId;
                }
                if (item.offerId) {
                    offers[item.offerId] = item.offerName || item.offerId;
                }
                if (item.chargeType) {
                    if (!chargeTypes[item.chargeType]) {
                        chargeTypes[item.chargeType] = 0;
                    }
                    chargeTypes[item.chargeType]++;
                }

                // Capture customer info from first item
                if (!customerName && item.customerName) {
                    customerName = item.customerName;
                }
                if (!currencyCode && item.currencyCode) {
                    currencyCode = item.currencyCode;
                    currencySymbol = item.currencySymbol || "";
                }
            }

            output.set("PretaxTotal", pretaxTotal);
            output.set("TaxTotal", taxTotal);
            output.set("AfterTaxTotal", afterTaxTotal);
            output.set("TotalQuantity", totalQuantity);
            output.set("CustomerName", customerName);
            output.set("CurrencyCode", currencyCode);
            output.set("CurrencySymbol", currencySymbol);

            output.set("UniqueSubscriptions", Object.keys(subscriptions).length);
            output.set("UniqueOffers", Object.keys(offers).length);

            // Build charge type breakdown
            var chargeTypeList = [];
            var ctKeys = Object.keys(chargeTypes);
            for (var j = 0; j < ctKeys.length; j++) {
                chargeTypeList.push({
                    type: ctKeys[j],
                    count: chargeTypes[ctKeys[j]]
                });
            }
            output.set("ChargeTypeBreakdown", json.stringify(chargeTypeList));

            output.set("HasErrors", false);
            output.set("ErrorMessage", "");

            log.info("Successfully retrieved " + items.length + " line items, total: " + currencySymbol + afterTaxTotal.toFixed(2));
            tags.trigger("success");
        } else {
            var errorMsg = "API returned status " + response.statusCode;
            try {
                var errorBody = json.parse(response.body);
                if (errorBody.message) errorMsg = errorBody.message;
                else if (errorBody.error_description) errorMsg = errorBody.error_description;
            } catch (e) {
                if (response.body) errorMsg = response.body.substring(0, 500);
            }

            log.error("Failed to retrieve service costs: " + errorMsg);
            output.set("HasErrors", true);
            output.set("ErrorMessage", errorMsg);
            tags.trigger("error");
        }
    } catch (ex) {
        log.error("Request failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Request failed: " + ex.message);
        output.set("StatusCode", 0);
        tags.trigger("error");
    }
}
